items.check_script:
# -*- coding: utf-8 -*-

import re

from items.common._base import BaseCheck


CHECK_COMMAND = 'dmidecode -t memory'


class Check(BaseCheck):
    USE_HOST_CONNECTION = True
    CONNECTION_METHOD = 'ssh'


    def parse_output(self, output):
        blocks = re.split(r'\n\s*Memory Device\s*\n', '\n' + (output or ''))
        devices = []
        for block in blocks[1:]:
            item = {}
            for line in block.splitlines():
                if ':' in line:
                    key, value = line.split(':', 1)
                    item[key.strip()] = value.strip()
            if item:
                devices.append(item)
        if not devices:
            return {'failure_type': 'parse_failure', 'reason': 'dmidecode memory device blocks were not found.'}
        return {'memory_device_count': len(devices), 'devices': devices}

    def evaluate(self, metrics, memory_device_required_fields):
        if metrics.get('failure_type'):
            return 'fail'
        required = [item.strip() for item in re.split(r'[|,\n]+', memory_device_required_fields or '') if item.strip()]
        bad = []
        for device in metrics['devices']:
            missing = [field for field in required if not device.get(field) or device.get(field) == 'No Module Installed']
            if missing:
                bad.append({'locator': device.get('Locator', ''), 'missing': missing})
        metrics['bad_devices'] = bad
        return 'fail' if bad else 'ok'

    def build_result(self, metrics, memory_device_required_fields, status):
        criteria = 'ok: every memory device has required fields: %s' % memory_device_required_fields
        if metrics.get('failure_type'):
            return {'message': 'memory recognition check failed.', 'results': metrics.get('reason', ''), 'criteria': criteria}
        results = 'memory_device_count=%d, bad_device_count=%d' % (metrics['memory_device_count'], len(metrics.get('bad_devices', [])))
        message = 'memory recognition check passed.' if status == 'ok' else 'memory recognition check failed policy.'
        return {'message': message, 'results': results, 'criteria': criteria}

    def run(self):
        memory_device_required_fields = self.get_threshold_var('memory_device_required_fields', default='Size|Type|Locator', value_type='str')

        rc, output, error = self._ssh(CHECK_COMMAND)

        if rc != 0:
            metrics = {
                'failure_type': 'command_failure',
                'rc': rc,
                'reason': (error or output or 'command failed').strip(),
            }
        else:
            metrics = self.parse_output(output)

        status = self.evaluate(metrics, memory_device_required_fields)
        result = self.build_result(metrics, memory_device_required_fields, status)

        return self.result(
            status=status,
            message=result['message'],
            metrics=metrics,
            results=result['results'],
            criteria=result['criteria'],
        )


CHECK_CLASS = Check
